 "content": "from collections import Counter

def transform(grid):
    """Transfer the interior motif of the unique 3x3 ring into each rectangular frame."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find the motif: an otherwise solid 3x3 color block with its center absent.
    motif = None
    for r in range(h - 2):
        for c in range(w - 2):
            cells = [grid[rr][cc] for rr in range(r, r + 3) for cc in range(c, c + 3)]
            counts = Counter(cells)
            color, n = counts.most_common(1)[0]
            if color != bg and n == 8 and grid[r + 1][c + 1] == bg:
                motif = color
                break
        if motif is not None:
            break
    if motif is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    # Each frame is a rectangle of one color with bg interior. Paint its interior
    # with the motif color; the frame's own original interior pattern identifies
    # the same 3x3 motif footprint when applicable.
    frames = []
    for color in set(v for row in grid for v in row if v != bg and v != motif):
        coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not coords:
            continue
        r0 = min(r for r, c in coords); r1 = max(r for r, c in coords)
        c0 = min(c for r, c in coords); c1 = max(c for r, c in coords)
        # The frame must be a solid rectangular outline, and its interior is empty.
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        border = all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1))
        if not border:
            continue
        if any(grid[r][c] != bg for r in range(r0+1,r1) for c in range(c0+1,c1)):
            continue
        # Match the motif's 3x3 inner footprint in the frame.
        frames.append((r0,r1,c0,c1))
    for r0,r1,c0,c1 in frames:
        # Rule inferred from demonstration: fill entire interior with output color.
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                out[r][c] = motif
    return out

if __name__ == '__main__':
    pass
